<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amsterdam - Movie Poster</title>
<script type="text/javascript" id="MathJax-script" async
  src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js">
</script>
<style>
  body {
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: center;
    background: #111;
  }

  .poster {
    width: 507px;
    min-height: 750px;
    background: radial-gradient(circle at 50% 40%, #1f3d2a 0%, #12241a 60%, #0c1a12 100%);
    position: relative;
    overflow: hidden;
    font-family: 'Arial Narrow', Arial, sans-serif;
    color: #fff;
    box-sizing: border-box;
  }

  .placeholder.rays {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 620px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(255,255,255,0.15);
    font-size: 12px;
    text-align: center;
    pointer-events: none;
    z-index: 0;
  }

  .cast-list {
    position: relative;
    z-index: 1;
    text-align: center;
    padding-top: 18px;
    line-height: 1.9;
  }

  .cast-list div {
    font-size: 18px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
  }

  .cast-list .with-line,
  .cast-list .and-line {
    font-size: 15px;
    font-weight: 400;
  }

  .cast-list .with-line span,
  .cast-list .and-line span {
    font-size: 18px;
    font-weight: 700;
  }

  .credit-block {
    position: absolute;
    bottom: 150px;
    width: 100%;
    text-align: center;
    font-size: 13px;
    line-height: 1.5;
    color: #eee;
    z-index: 1;
  }

  .title {
    position: absolute;
    bottom: 60px;
    width: 100%;
    text-align: center;
    font-size: 58px;
    font-weight: 900;
    color: #e0a52e;
    letter-spacing: 2px;
    font-family: 'Georgia', 'Times New Roman', serif;
    z-index: 1;
  }

  .release-info {
    position: absolute;
    bottom: 25px;
    width: 100%;
    text-align: center;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1px;
    color: #f0c25a;
    z-index: 1;
  }

  .release-info .theaters {
    color: #fff;
    font-weight: 400;
    letter-spacing: 2px;
  }

  .footer-row {
    position: absolute;
    bottom: 5px;
    width: 100%;
    display: flex;
    justify-content: space-between;
    padding: 0 20px;
    box-sizing: border-box;
    z-index: 1;
  }

  .placeholder.small-logo {
    width: 60px;
    height: 18px;
    font-size: 7px;
    color: rgba(255,255,255,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
  }
</style>
</head>
<body>

<div class="poster">

  <div class="placeholder rays">[Diagram: sunburst/wavy rays radiating from center, olive-green background]</div>

  <div class="cast-list">
    <div>Christian Bale</div>
    <div>Margot Robbie</div>
    <div>John David Washington</div>
    <div>Chris Rock</div>
    <div>Anya Taylor-Joy</div>
    <div>Zoe Saldaña</div>
    <div>Mike Myers</div>
    <div>Michael Shannon</div>
    <div>Timothy Olyphant</div>
    <div>Andrea Riseborough</div>
    <div>Taylor Swift</div>
    <div>Matthias Schoenaerts</div>
    <div>Alessandro Nivola</div>
    <div class="with-line">with <span>Rami Malek</span></div>
    <div class="and-line">and <span>Robert De Niro</span></div>
  </div>

  <div class="credit-block">
    From the Director of<br>
    American Hustle and Silver Linings Playbook
  </div>

  <div class="title">AMSTERDAM</div>

  <div class="release-info">
    <div class="theaters">ONLY IN THEATERS</div>
    <div>NOVEMBER 2022</div>
  </div>

  <div class="footer-row">
    <div class="placeholder small-logo">[Logo: studio, bottom-left]</div>
    <div class="placeholder small-logo">[Logo: studio, bottom-right]</div>
  </div>

</div>

</body>
</html>
```
